      "module_name": "Mathlib.RingTheory.Algebraic.Integral",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} [inst : CommRing R] [inst_1 : Ring A] [inst_2 : Algebra R A] {z : A},\n  IsAlgebraic R z → ∃ y, y ≠ 0 ∧ IsIntegral R (y • z)"
    },
    {
      "name": "IsAlgebraic",
      "module_name": "Mathlib.RingTheory.Algebraic.Defs",
      "kind": "definition",
      "type": "(R : Type u) → {A : Type v} → [inst : CommRing R] → [inst_1 : Ring A] → [Algebra R A] → A → Prop"
    },
    {
      "name": "Algebra.isAlgebraic_iff_isIntegral",
      "module_name": "Mathlib.RingTheory.Algebraic.Integral",
      "kind": "theorem",
      "type": "∀ {K : Type u} {A : Type v} [inst : Field K] [inst_1 : Ring A] [inst_2 : Algebra K A],\n  Algebra.IsAlgebraic K A ↔ Algebra.IsIntegral K A"
    },
    {
      "name": "Algebra.IsAlgebraic",
      "module_name": "Mathlib.RingTheory.Algebraic.Defs",
