      "type": "(R : Type u) → (A : Type v) → [inst : CommRing R] → [inst_1 : Ring A] → [Algebra R A] → Prop"
    },
    {
      "name": "Algebra.isAlgebraic_def",
      "module_name": "Mathlib.RingTheory.Algebraic.Defs",
      "kind": "theorem",
      "type": "∀ {R : Type u} {A : Type v} [inst : CommRing R] [inst_1 : Ring A] [inst_2 : Algebra R A],\n  Algebra.IsAlgebraic R A ↔ ∀ (x : A), IsAlgebraic R x"
    },
    {
      "name": "IsAlgebraic.smul",
      "module_name": "Mathlib.RingTheory.Algebraic.Integral",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} [inst : CommRing R] [inst_1 : Ring A] [inst_2 : Algebra R A] {a : A},\n  IsAlgebraic R a → ∀ (r : R), IsAlgebraic R (r • a)"
    },
    {
      "name": "isAlgebraic_iff_isIntegral",
      "module_name": "Mathlib.RingTheory.Algebraic.Integral",
      "kind": "theorem",
      "type": "∀ {K : Type u} {A : Type v} [inst : Field K] [inst_1 : Ring A] [inst_2 : Algebra K A] {x : A},\n  IsAlgebraic K x ↔ IsIntegral K x"
